import random
def backoff(attempt, base=0.1, cap=10.0):
    return random.uniform(0, min(cap, base * 2 ** attempt))

def price(sku):
    try:
        p = pricing.get(sku, timeout=0.3)
        cache.set(f'price:{sku}', p, ttl=3600)
        return p, False
    except (Timeout, CircuitOpen):
        cached = cache.get(f'price:{sku}')
        if cached: return cached, True   # degraded
        raise
